msg.url = 'https://apis.map.qq.com/ws/location/v1/network';
msg.method = "POST";
msg.headers = {
    'Content-Type': 'application/json',
};

if(msg.payload.node_type == 0)  // reference node
    return [msg, null];

if(msg.payload.node_type != 1) {
    node.error("Error! node_type != 1");
    return [null, null];
}



// re-assemble payload 'c56409804c76c3ac74d6cb9c74f7c1045fb9e67d60ca62c0a25b465caf603a7cac81de'

let idx = 2;  // the beginning byte is for payload_type (wifi tag)
let wifiinfo = [];

while(idx < msg.payload.app_data.length){
  let rssi = parseInt(msg.payload.app_data.slice(idx, idx+2), 16) - 256;
  let mac = msg.payload.app_data.slice(idx+2, idx+14);
  idx += 14;

  let wifi = {
    "mac": mac,
    "rssi": rssi
  }

  wifiinfo.push(wifi);
}

let query_msg = {
    "key": "RVYBZ-BFNWU-JALV7-2CTQC-ASD6E-E4F5W",
    "device_id": msg.payload.name,
    "wifiinfo": wifiinfo
}
msg.node_info = msg.payload;
msg.payload = query_msg;

return [null, msg];

var payload_in;                                                                       

try {
  payload_in = (JSON.parse(msg.payload));                                             
} catch(err) {
  node.error("Unable to parse input as JSON string", msg);                            
  return [null, null];                                                                
}                                                                                     

let port = parseInt(payload_in.fPort, 10);                                                

if(port != 66) 
  return [msg, null];                                                                 

let deveui = payload_in.deviceInfo.devEui.toUpperCase();
let data = Buffer.from(payload_in.data, 'base64'); 
msg.data = data;
data = data.toString('hex');
//console.log(payload.toString('hex'))                                                
//*
let node_type = parseInt(data.slice(0, 2), 16); 
let ht_l = parseInt(data.slice(2, 4), 16);                                            
let ht_h = parseInt(data.slice(4, 6), 16);       
//*/
/*
let node_type = data[0];
let ht_l = data[1];                                            
let ht_h = data[2];
*/
let height = ht_h << 8 | ht_l;

if(height > 32767)
    height -= 65536;
let baro_pld_len = 6;  // 3 bytes, and 1 byte = 2 hex values
let app_data = data.slice(baro_pld_len, data.length);                  

let info = {
    "name": deveui,
    "node_type": node_type,                                                           
    "height": height,
    "app_data": app_data                                                              
}
msg.old_payload = msg.payload;                                                        
msg.payload = info;                                                                   

return [null, msg];

let ref = {}
let cal_ref = null

for(const [k, v] of Object.entries(msg.payload)){
  ref[k] = {
    'base_off': null,
    'ht': [],  // [time, height]
    'cal_base': false  // calibrate base; only node at the 1st floor is true
  }

  if(v == 1){
    ref[k]['cal_base'] = true
    cal_ref = k
    console.log('cali base: %s', k)
  }
}

global.set('ref', ref)
global.set('cal_ref', cal_ref)
msg.payload = ref

return msg

let floor_db = {}  // reverse ref_db, use floor number as key, node name as value

for(const [k, v] of Object.entries(msg.payload)){
  floor_db[v] = k
}

global.set('floor_db', floor_db)
msg.payload = floor_db

return msg;

const digital_multi = 10  // shift left one digital, means all height values are 10 times bigger
const above_from_ground = 2; // 0; // 1 * digital_multi

let ref = global.get('ref') || {};
let floor_db = global.get('floor_db') || {};
let cal_ref = global.get('cal_ref') || null;
let dbg_msg = "";


// fl/fh: floor low/high; hl/hh: height low/hight; ht: node height
function calc_which_floor(fl, fh, hl, hh, ht) {
    console.log('fl =', fl, 'fh =', fh, 'hl =', hl, 'hh =', hh, 'ht =', ht, 'above_from_ground =', above_from_ground)
    dbg_msg += 'fl = ' + fl + ', fh = ' + fh + ', hl = ' + hl + ', hh = ' + hh
    dbg_msg += ', ht =' + ht + ', above_from_ground =' + above_from_ground + '\n'

    if(ht == hl){
        console.log("same height as floor %s", fl)
        dbg_msg += "same height as floor " + fl + '\n'
        msg.payload.which_floor_detail = fl
        return fl
    } else if (ht == hh){
        console.log("same height as floor %s", fh)
        dbg_msg += "same height as floor " + fh + '\n'
        msg.payload.which_floor_detail = fh
        return fh
    }

    let nf = fh - fl
    let one_flr_ht = (parseFloat(hh - hl) / nf).toFixed(1)
    console.log('one_flr_ht = %s', one_flr_ht)
    dbg_msg += 'one_flr_ht = ' + one_flr_ht + '\n'
    let node_flrs = parseFloat(ht - hl + above_from_ground) / parseFloat(one_flr_ht)
    console.log('node_flrs = %s', node_flrs)
    dbg_msg += 'node_flrs = ' + node_flrs + '\n'

    let flr_num_detail = parseFloat(node_flrs.toFixed(1)) + parseInt(fl)
    if(parseInt(node_flrs) < 0){
        flr_num_detail -= 2  // let's skip floor 0, and if node_flrs == -0.2, then it's in floor -1
    }
    msg.payload.which_floor_detail = flr_num_detail

    let flr_num = parseInt(node_flrs) + parseInt(fl)
    if(parseInt(node_flrs) < 0){
        flr_num -= 2  // let's skip floor 0, and if node_flrs == -0.2, then it's in floor -1
    }
    return flr_num
}


function find_bottom_top(ht) {
    let floors = []
    let all_floors = Object.keys(floor_db)
    all_floors.sort()
    let ref_ht_list = []
    for (let x of all_floors){
        if(ref[ floor_db[x] ]['ht'] != false){
            console.log("x = ", x, 'floor_db[x]', floor_db[x], 'ref =', ref[ floor_db[x] ]['ht'])
            floors.push(x)
            ref_ht_list.push(ref[ floor_db[x] ]['ht'][1] - ref[ floor_db[x] ]['base_off'])
        }
    }
    let frl = floors.length
    let refl = ref_ht_list.length

    let which_floor
    if(ht < ref_ht_list[0]){
        console.log("below floor %s: %s < %s", floors[0], ht, ref_ht_list[0])
        dbg_msg += "below floor " + floors[0] + ": " + ht + " < " + ref_ht_list[0] + "\n"
        which_floor = calc_which_floor(floors[0], floors[1], ref_ht_list[0], ref_ht_list[1], ht)
    } else if(ht > ref_ht_list[refl-1]){
        console.log("above floor [%s]: %s < %s", floors[frl-1], ht, ref_ht_list[refl-1])
        dbg_msg += "above floor [" + floors[frl-1] + "]: " + ht + " < " + ref_ht_list[refl-1] + "\n"
        which_floor = calc_which_floor(floors[frl-2], floors[frl-1], ref_ht_list[refl-2], ref_ht_list[refl-1], ht)
    } else {
        let i = 1
        while(ht >= ref_ht_list[i]){
            i += 1
        }
        //l, h = floor_db[floors[i-1]], floor_db[floors[i]]
        let l = floors[i-1]
        let h = floors[i]
        console.log("between floors [%s, %s]: %s < %s < %s", l, h, ref_ht_list[i-1], ht, ref_ht_list[i])
        dbg_msg += "between floors [" + l + ", " + h + "]: " + ref_ht_list[i-1] + " < " + ht + " < " + ref_ht_list[i] + "\n"
        which_floor = calc_which_floor(l, h, ref_ht_list[i-1], ref_ht_list[i], ht)
    }

    console.log("node in floor = %s", which_floor)
    dbg_msg += "node in floor = " + which_floor + "\n"
    msg.payload.which_floor = which_floor
}


function process_mobile_node(name, ht) {
  let node = global.get('node') || {}
  if (!(name in node)) {
    console.log('name not in node')
    dbg_msg += "first data from node for calibration"
    if(cal_ref in ref && ref[cal_ref]['base_off0'] != null){
      let tmp_off = ht - ref[cal_ref]['base_off0']
      console.log('node (%s) has base_off = %s', name, tmp_off)
      dbg_msg += 'node (' + name + ') has base_off = ' + tmp_off + '\n'
      node[name] = { 'base_off': tmp_off }
      global.set('node', node)
    }
  } else {  // try to calculate floor number
    console.log('calculate floor with %s', ht)
    dbg_msg += 'calculate floor with ' + ht + '\n'
    let node_ht = ht - node[name]['base_off']
    find_bottom_top(node_ht)
  }
}


function process_payload(pld) {
    //let obj = JSON.parse(pld)
    let name = pld['name']
    let ht = pld['height']
    if(name in ref){
        if(ref[name]['base_off'] == null){
            if(name == cal_ref){
                ref[name]['base_off'] = 0
                ref[name]['base_off0'] = ht
                ref[name]['ht'] = [new Date().getTime() / 1000, ht]
            } else if(ref[cal_ref]['base_off0']){
                ref[name]['base_off'] = ht - ref[cal_ref]['base_off0']
                ref[name]['ht'] = [new Date().getTime() / 1000, ht]
            } else {
                ref[name]['ht'] = [new Date().getTime() / 1000, ht]
                console.log("warn: cal_ref.base_off not available; ref[%s]['base_off'] doesn't update", name)
                dbg_msg += "warn: cal_ref.base_off not available; ref[" + name + "]['base_off'] doesn't update" + '\n'
            }
        } else {
            ref[name]['ht'] = [new Date().getTime() / 1000, ht]
        }
        console.log(ref)
        dbg_msg += JSON.stringify(ref) + '\n'
    } else {
        console.log('\ngot node, name = %s', name)
        dbg_msg += "got data from node '" + name + "'\n"
        process_mobile_node(name, ht)
    }
}


process_payload(msg.payload)

msg.dbg_msg = dbg_msg;
return msg;

if (msg.payload.result === null) return;
if (msg.payload.result.location === null) return;

const devEui = msg.node_info.name.match( /.{1,2}/g ).join( '-' );
try {
    const lat = msg.payload.result.location.latitude;
    const lon = msg.payload.result.location.longitude;

    let which_floor = "(unknown)"
    if(msg.node_info.which_floor)
        which_floor = msg.node_info.which_floor + "(detail: " + msg.node_info.which_floor_detail + ")";

    msg.payload = {
        "name": devEui,
        "lat": lat,
        "lon": lon,
        "time": `${new Date(Date.now())}`,
        "which_floor": which_floor,
        "icon": "fa-wifi",
        "ttl": 86400, // 24 hours
        "color":"#008000",
        "command": {
            "lat": lat,
            "lon": lon,
            "layer": "OSM"
        }
    }
    return msg;
} catch(err) {
    return null;
}

// start of convert GCJ-2 to GPS-84
const pi = 3.14159265358979;
const a = 6378245.0;
const ee = 0.0066934216229659;

function transformLat(x, y) {
  var ret = -100.0 + 2.0 * x + 3.0 * y + 0.2 * y * y + 0.1 * x * y + 0.2 * Math.sqrt(Math.abs(x));
  ret += (20.0 * Math.sin(6.0 * x * pi) + 20.0 * Math.sin(2.0 * x * pi)) * 2.0 / 3.0;
  ret += (20.0 * Math.sin(y * pi) + 40.0 * Math.sin(y / 3.0 * pi)) * 2.0 / 3.0;
  ret += (160.0 * Math.sin(y / 12.0 * pi) + 320 * Math.sin(y * pi / 30.0)) * 2.0 / 3.0;
  return ret;
}

function transformLon(x, y) {
  var ret = 300.0 + x + 2.0 * y + 0.1 * x * x + 0.1 * x * y + 0.1 * Math.sqrt(Math.abs(x));
  ret += (20.0 * Math.sin(6.0 * x * pi) + 20.0 * Math.sin(2.0 * x * pi)) * 2.0 / 3.0;
  ret += (20.0 * Math.sin(x * pi) + 40.0 * Math.sin(x / 3.0 * pi)) * 2.0 / 3.0;
  ret += (150.0 * Math.sin(x / 12.0 * pi) + 300.0 * Math.sin(x / 30.0 * pi)) * 2.0 / 3.0;
  return ret;
}

function transform(lat, lon) {
  var dLat = transformLat(lon - 105.0, lat - 35.0);
  var dLon = transformLon(lon - 105.0, lat - 35.0);
  var radLat = lat / 180.0 * pi;
  var magic = Math.sin(radLat);
  magic = 1 - ee * magic * magic;
  var sqrtMagic = Math.sqrt(magic);

  dLat = (dLat * 180.0) / ((a * (1 - ee)) / (magic * sqrtMagic) * pi);
  dLon = (dLon * 180.0) / (a / sqrtMagic * Math.cos(radLat) * pi);

  var mgLat = lat + dLat;
  var mgLon = lon + dLon;
  return [mgLat, mgLon];
}

function gcj02_To_Gps84(lat, lon) {
  var gps = transform(lat, lon);
  var lontitude = lon * 2 - gps[1];
  var latitude = lat * 2 - gps[0];
  return [latitude.toFixed(6), lontitude.toFixed(6)];
}
// end of convert GCJ-2 to GPS-84

try {
    const lat = msg.payload.lat;
    const lon = msg.payload.lon;
    let geo = gcj02_To_Gps84(lat, lon);

    msg.payload = {
        "name": msg.payload.name,
        "lat": geo[0],
        "lon": geo[1],
        "time": `${new Date(Date.now())}`,
        "which_floor": msg.payload.which_floor,
        "icon": "fa-wifi",
        "ttl": 86400, // 24 hours
        "color":"#008000",
        "command": {
            "lat": geo[0],
            "lon": geo[1],
            "layer": "OSM"
        }
    }
    return msg;
} catch(err) {
    return null;
}
